

import { TrieNode } from "./trieNode"


class TrieSorted {

    root: TrieNode;

    constructor() {
        this.root = new TrieNode();
    }

    print() {
        this.printNode(this.root)
    }

    printNode(node: TrieNode) {

        for (let k in node.children) {
            //console.log(k);
            this.printNode(node.children[k])
        }
    }

    insert(word: string): void {

        let node = this.root;

        for (let ch of word) {
            if (!node.children[ch]) {
                let n = new TrieNode();
                let i = 0;
                for (let char in node.children) {
                    if (char > ch) {
                        break;
                    }
                    i++
                }

                node.children = this.insertIntoJsonAt(node.children, i, ch, n);

                //console.log(node);

            }
            node = node.children[ch];
        }

        node.isEnd = true;
    }

    insertIntoJsonAt(obj: any, index: number, newKey: string, newValue: TrieNode) {
        const entries = Object.entries(obj);
        entries.splice(index, 0, [newKey, newValue]);
        return Object.fromEntries(entries);
    }
    search(word: string): boolean {

        let node = this.root;

        for (let ch of word) {
            if (!node.children[ch]) {
                return false;
            }
            else {
                node = node.children[ch]!;
            }
        }

        return node.isEnd;
    }

    startsWith(prefix: string): boolean {

        let node = this.root;

        for (let ch of prefix) {
            if (!node.children[ch]) {
                return false;
            }
            else {
                node = node.children[ch]!;
            }
        }

        return true;
    }


    suggest(prefix: string, node: TrieNode) {

        // for (let ch of prefix) {
        //     if (!node.children[ch]) {
        //         break;
        //     }
        //     else {
        //         node = node.children[ch]!;
        //     }
        // }

        //console.log("For " + prefix);

        let res: string[] = []

        if (node.isEnd) res.push(prefix);

        let a = this.suggestWords(node, prefix, res);

        //console.log(res);

        return res;
    }

    suggestWords(node: TrieNode, s: string, res: string[]) {

        for (const [ch, n] of Object.entries(node.children)) {

            if (res.length > 2) return;

            if ((n as TrieNode).isEnd) {
                let a = s + ch;
                if (a.length > 0)
                    res.push(a);
            }

            this.suggestWords(n as TrieNode, s + ch, res);
        }

        return
    }


}


function suggestedProducts(products: string[], searchWord: string): string[][] {

    var objT = new TrieSorted()

    for (let p of products) {
        objT.insert(p);
    }

    let prefix = "";
    let node = objT.root;
    let res = [];

    for (let ch of searchWord) {
        prefix = prefix + ch;
        if (node.children[ch]) {
            node = node.children[ch];
            res.push(objT.suggest(prefix, node))
        }
        else {
            break;
        }
    }

    console.log(res.length, searchWord.length)

    let a = searchWord.length - res.length;
    let r = new Array(a).fill([]);
    console.log(r);
    res.push(...r)

 
    return res;

};



